starterCode:
from fastapi import FastAPI

app = FastAPI()


@app.get("/add")
def add(a, b):
    return {"sum": a + b}

solution:
from fastapi import FastAPI

app = FastAPI()


@app.get("/add")
def add(a: int, b: int):
    return {"sum": a + b}

